func (s R10NetZero) JSONSize() int {
	size := 28
	if s.Addr.Is4() {
		size += 15
	} else {
		size += 39
	}
	if z := len(s.Addr.Zone()); z > 0 {
		size += 1 + z*2
	}
	if s.IP.To4() != nil {
		size += 15
	} else if len(s.IP) != 0 {
		size += 39
	} else {
		size += 2
	}
	if s.Pfx.Addr().Is4() {
		size += 19
	} else {
		size += 43
	}
	return size
}

func (s R10NetZero) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"addr\":\""...)
	dst = ggen.AppendNetipAddr(dst, s.Addr)
	dst = append(dst, ",\"ip\":\""...)
	if dst, err = s.IP.AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"pfx\":\""...)
	if dst, err = s.Pfx.AppendText(dst); err != nil {
		return dst, err
	}
	return append(dst, "\"}"...), nil
}

